import { mapGetters } from 'vuex'
// import Upload from '@/components/Upload/index'

import { selectShortNameTree, selectShoutUser, machineRoomUserAdd, machineRoomUserEdit, userDetail } from "@/api/safeDanger/hiddenCategory"
import {categoryTree} from "@/api/safeDanger/supervisionUnit"
import { updateHidden } from "@/api/safeDanger/rectificationImport"

export default {
  name: "ComputerRoomDetail",
  // components: {Upload},
  computed: {
    ...mapGetters([
      'nickName',
      'companyId',
      'companyCode',
      'userId'
    ]),
  },
  props: {
    roomId: {
      type: Number,
    },
    detailId: {
      type: Number,
    },
    detailObj: {
      type: Object
    },
    isEdit: {
      type: Boolean,
      default: false
    },
    isInfo: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      defaultProps: {
        value: 'id',
        label: 'name',
        leaf: 'leaf',
        children: 'children',
        // checkStrictly: true,
        // emitPath: false,
        expandTrigger: 'hover'
      },

      // 表单参数
      formData: {
        secondCompany: undefined,
        userIdList: [],
      },

      //校验
      rules:{

        secondCompany:[{required:true, type: 'array', message:'请选择责任单位', trigger:'change'}],
        userIdList:[{required:true, message:'请选择责任人', trigger:'change'}],

      },



      // 下拉列表
      basicUnitSeconds: [],
      userList: [],

    }
  },
  created() {
    this.initData()
    this.showInfo();
  },
  mounted() {

  },
  methods: {
    secondCompanyChange(val){
      this.formData.userIdList = ''
      if(val.length > 0){
        selectShoutUser({ regionCode: val[2] }).then(res=>{
          this.userList = res.data.records
        })
      }
    },
    // 渲染表格
    showInfo() {
      if(this.detailId){
        userDetail( { categoryId: this.detailId, regionCode: this.detailObj.regionCode } ).then(res=>{
          // if(res.data.length>0){
            // this.formData = res.data[0]
            // let datas = res.data
            let data = res.data
            this.formData.secondCompany = [ data.firstCode, data.secondCode, data.regionCode ]

            selectShoutUser({ regionCode: data.regionCode }).then(res=>{
              this.userList = res.data.records
              this.formData.userIdList = data.userList.split(',')
            })
          // }

        })
      }
    },

    /** 提交按钮 */
    submitForm: function() {
      // this.formData.firstCompany = this.companyCode.slice(0, 4)
      this.$refs["form"].validate(valid => {
        if (valid) {
          let params = {
            categoryId: this.roomId,
            // orgCode: this.formData.secondCompany[0],
            // firstCompany: this.formData.secondCompany[1],
            regionCode: this.formData.secondCompany[2],
            userIdList: this.formData.userIdList
          }

          if(this.detailId){
            params.id = this.detailId
            machineRoomUserEdit(params).then(res=>{
              this.$message.success(res.msg)
              this.$emit('closeRoom')
            })
          }else{
            machineRoomUserAdd(params).then(res=>{
              this.$message.success(res.msg)
              this.$emit('closeRoom')
            })
          }


          // let forms = JSON.parse(JSON.stringify(this.formData))

          // updateHidden(forms).then(response => {
          //   if (response.code === 200) {
          //     this.msgSuccess("修改成功");
          //     this.$emit('closeRoom', response.data)
          //   } else {
          //     this.msgError(response.msg);
          //   }
          // });
        }
      });
    },

    // 获取下拉列表
    initData(){
      // selectShortNameTree().then(res=>{
      //   this.basicUnitSeconds = res.data
      // })

      categoryTree().then(response => {
        this.basicUnitSeconds = response.data
      })
    },






  }
}
